const execution = $input.item.json.execution || {};
const workflow = $input.item.json.workflow || {};
const error = execution.error || {};

const incidentAlert = {
  severity: 'HIGH',
  system: 'LendLoop Automation Engine',
  workflowName: workflow.name || 'Unknown Workflow',
  workflowId: workflow.id || 'N/A',
  executionId: execution.id || 'N/A',
  failedNode: execution.lastNodeExecuted || 'Unknown Node',
  errorMessage: error.message || 'Unknown execution failure',
  timestamp: new Date().toISOString()
};

console.error('[CRITICAL AUTOMATION FAILURE ALERT]', JSON.stringify(incidentAlert));

return [{ json: incidentAlert }];
